    fbBuilder.addFloat64(14, _CEP95_M);
    fbBuilder.addFloat64(15, _GDOP);
    fbBuilder.addFloat64(16, _VELOCITY_EAST_M_S);
    fbBuilder.addFloat64(17, _VELOCITY_NORTH_M_S);
